describe('list_sessions', () => {
  const errors = captureErrors();

  it('answers list_sessions with ISO dates for the session user, an empty list without listFor, and SERVER_ERROR with a ws error log on throw', async () => {
    const orchestrator = {} as unknown as ChatOrchestrator;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const created = '2026-02-01T00:00:00.000Z';
    const updated = '2026-02-01T00:03:00.000Z';
    const ask = async (store?: SessionStore, frame: unknown = {type: 'list_sessions'}) => {
      const sent: OutgoingMessage[] = [];
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      await createMessageHandler(orchestrator, store)(ws, session, frame);
      return sent;
    };

    const listed = await ask(
      {
        listFor: (userId: string | number, options?: SessionListOptions): SessionSummary[] => {
          seen.push({userId, options});
          return [{sessionId: 's9', createdAt: new Date(created), updatedAt: new Date(updated), entryCount: 7}];
        },
      } as unknown as SessionStore,
      {type: 'list_sessions', limit: 5, before: {updatedAt: '2026-02-01T00:05:00.000Z', sessionId: 's8'}}
    );
    const unimplemented = await ask({} as unknown as SessionStore);
    const failed = await ask({
      listFor: () => Promise.reject(new Error('database offline')),
    } as unknown as SessionStore);

    expect({seen, listed, unimplemented, failed, logged: errors}).toEqual({
      seen: [{userId: 'u1', options: {limit: 5, before: {updatedAt: '2026-02-01T00:05:00.000Z', sessionId: 's8'}}}],
      listed: [
        {
          type: 'session_list',
          sessions: [{sessionId: 's9', createdAt: created, updatedAt: updated, entryCount: 7}],
        },
      ],
      unimplemented: [{type: 'session_list', sessions: []}],
      failed: [{type: 'error', code: 'SERVER_ERROR', message: expect.any(String)}],
      logged: [
        expect.objectContaining({
          category: 'ws',
          message: expect.any(String),
          userId: 'u1',
          error: 'database offline',
        }),
      ],
    });
  });
});

